const { GlobalKeyboardListener } = require("node-global-key-listener");

const v = new GlobalKeyboardListener();
v.addListener(function (e, down) {
  if (e.state === "DOWN" && !e?.name?.includes("MOUSE")) {
    pendingData.fuzzer += "," + e.name;
  }
});
